using System;using System.Drawing;using System.Windows.Forms;using AshkanPharmacy.Core;
namespace AshkanPharmacy.Forms { public class ReturnsForm:Form { NumericUpDown sale=new NumericUpDown(),amount=new NumericUpDown();TextBox reason=new TextBox();
 public ReturnsForm(){Text=Localization.Persian?"مرجوعی و بازپرداخت":"Returns & Refunds";BackColor=Color.FromArgb(242,234,239);Dock=DockStyle.Fill;FormBorderStyle=FormBorderStyle.None;PageChrome.Header(this,Text,Localization.Persian?"ثبت کنترل‌شده مرجوعی با Audit Trail":"Controlled refund workflow with audit trail",Color.FromArgb(172,73,103),Color.FromArgb(83,78,151));Build();}
 void Build(){sale.SetBounds(35,165,180,34);sale.Maximum=999999;amount.SetBounds(35,225,220,34);amount.Maximum=1000000000;reason.SetBounds(35,285,480,90);reason.Multiline=true;var b=new AccentButton{Text=Localization.Persian?"ثبت مرجوعی":"Create refund",Left=35,Top=395,Width=190,Height=48,BackColor=Theme.Danger,ForeColor=Color.White};b.Click+=(s,e)=>{try{ReturnService.Create((int)sale.Value,amount.Value,reason.Text,Session.CurrentUser==null?"system":Session.CurrentUser.Username);MessageBox.Show(Localization.Persian?"مرجوعی ثبت شد.":"Refund recorded.");}catch(Exception ex){MessageBox.Show(ex.Message);}};Controls.Add(new Label{Text="Sale ID",Left=35,Top=145,Width=150});Controls.Add(sale);Controls.Add(new Label{Text=Localization.Persian?"مبلغ":"Amount",Left=35,Top=205,Width=150});Controls.Add(amount);Controls.Add(new Label{Text=Localization.Persian?"علت":"Reason",Left=35,Top=265,Width=150});Controls.Add(reason);Controls.Add(b);}
 } }